full = pd.read_csv('/root/output/unified_taxonomy_full.csv')

# function to token set from label

def tokens(label):
    if not isinstance(label, str) or label == '':
        return set()
    return set(t.strip().lower() for t in label.split('|') if t.strip())

violations = []
for _, row in full.iterrows():
    levels = [row['unified_level_1'], row['unified_level_2'], row['unified_level_3'], row['unified_level_4'], row['unified_level_5']]
    for i in range(1,5):
        parent = levels[i-1]
        child = levels[i]
        if not child or not isinstance(child,str):
            continue
        if tokens(parent) & tokens(child):
            violations.append((parent, child))

print('overlap pairs', len(violations))
# show sample
print(violations[:10])
