import pandas as pd
import itertools

full = pd.read_csv('/root/output/unified_taxonomy_full.csv')


def tokens(label):
    return [t.strip().lower() for t in str(label).split('|') if t.strip()]

viol = 0
for parent_cols, child_col in [
    (['unified_level_1'],'unified_level_2'),
    (['unified_level_1','unified_level_2'],'unified_level_3'),
]:
    for parents, grp in full.groupby(parent_cols):
        kids = sorted(set([c for c in grp[child_col] if isinstance(c,str) and c!='']))
        for a,b in itertools.combinations(kids,2):
            ta, tb = set(tokens(a)), set(tokens(b))
            if not ta or not tb:
                continue
            overlap = len(ta & tb) / max(len(ta), len(tb))
            if overlap >= 0.3:
                viol += 1
                break
        if viol:
            break
    if viol:
        break

print('overlap violations found:', viol)
